// Fox and Fiddle asset catalog: loads catalog.json (generated by `npm run catalog`) and renders a
// searchable, filterable, sortable grid with a detail view. State lives in the URL hash so links
// to a search, a category or a single asset can be shared.
(function () {
  'use strict';

  const $ = (s) => document.querySelector(s);
  const el = (tag, cls, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; };
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  let data = null, catLabel = {}, catOrder = {};
  const state = { q: '', cat: 'all', sort: 'category', dir: 1, asset: null };
  let visible = [];

  // ---------- formatting ----------
  function len(m) {
    if (m == null) return '—';
    if (m >= 1) return `${m.toFixed(2)} m`;
    if (m >= 0.1) return `${Math.round(m * 100)} cm`;
    return `${Math.round(m * 1000)} mm`;
  }
  function dimsLine(d) {
    if (!d) return '';
    const max = Math.max(d.w, d.h, d.d);
    const unit = max >= 1 ? 'm' : max >= 0.1 ? 'cm' : 'mm';
    const f = (v) => unit === 'm' ? v.toFixed(2) : unit === 'cm' ? String(Math.round(v * 100)) : String(Math.round(v * 1000));
    return `${f(d.w)} × ${f(d.h)} × ${f(d.d)} ${unit}`;
  }
  const num = (n) => (n ?? 0).toLocaleString();

  // ---------- search ----------
  function haystack(a) {
    if (!a._hay) a._hay = [a.name, a.id, catLabel[a.category], ...(a.categories || []).map((c) => catLabel[c]), ...(a.tags || []), a.description, ...(a.usedIn || []), ...(a.notes || []), a.source, a.textureSize].join(' \n ').toLowerCase();
    return a._hay;
  }
  function matches(a, terms) { const h = haystack(a); return terms.every((t) => h.includes(t)); }
  /** How well an asset matches: a hit in the name beats a tag, which beats a mention in the notes. */
  function relevance(a, terms) {
    if (!a._fields) {
      const lc = (x) => String(x ?? '').toLowerCase();
      a._fields = [
        [6, lc(a.name)], [4, lc(a.id)], [3, lc((a.tags || []).join(' '))], [2, lc((a.categories || []).map((c) => catLabel[c]).join(' '))],
        [1.5, lc((a.usedIn || []).join(' '))], [1, lc(a.description)], [0.5, lc((a.notes || []).join(' ') + ' ' + a.source)],
      ];
    }
    let score = 0;
    for (const t of terms) { let best = 0; for (const [w, f] of a._fields) if (w > best && f.includes(t)) best = w; score += best; }
    return score;
  }
  function highlight(text, terms) {
    let out = esc(text);
    for (const t of terms) { if (t.length < 2) continue; out = out.replace(new RegExp(`(${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'ig'), '<mark>$1</mark>'); }
    return out;
  }

  // ---------- sorting ----------
  const key = {
    name: (a) => a.name.toLowerCase(),
    category: (a) => catOrder[a.category] * 1000,
    size: (a) => a.dims ? Math.max(a.dims.w, a.dims.h, a.dims.d) : null,
    height: (a) => a.dims ? a.dims.h : null,
    footprint: (a) => a.dims ? a.dims.w * a.dims.d : null,
    tris: (a) => a.tris ?? null,
    instances: (a) => a.instances ?? (a.kind === 'texture' || a.kind === 'file' ? null : 1),
    relevance: (a) => -relevance(a, terms_()) * 1e6 + catOrder[a.category],
  };
  function sortAssets(list) {
    const k = key[state.sort];
    return list.slice().sort((a, b) => {
      const ka = k(a), kb = k(b);
      if (ka == null && kb == null) return a.name.localeCompare(b.name);
      if (ka == null) return 1; if (kb == null) return -1;           // unmeasured items always last
      const c = typeof ka === 'string' ? ka.localeCompare(kb) : ka - kb;
      return c !== 0 ? c * state.dir : a.name.localeCompare(b.name);
    });
  }

  // ---------- rendering ----------
  function heroOf(a) { const v = a.views.find((x) => x.view === 'hero') || a.views[0]; return v && v.file; }
  const isFlat = (a) => a.kind === 'texture' || a.kind === 'file';

  function renderCats() {
    const nav = $('#cats'); nav.innerHTML = '';
    const terms = terms_();
    const pool = data.assets.filter((a) => matches(a, terms));
    const counts = { all: pool.length };
    for (const a of pool) for (const c of a.categories) counts[c] = (counts[c] || 0) + 1;
    const mk = (id, label) => {
      const b = el('button', 'cat', `${esc(label)} <b>${counts[id] || 0}</b>`);
      b.setAttribute('aria-pressed', String(state.cat === id));
      b.onclick = () => { state.cat = id; update(); };
      nav.append(b);
    };
    mk('all', 'All');
    for (const c of data.categories) if (data.assets.some((a) => a.categories.includes(c.id))) mk(c.id, c.label);
  }

  function terms_() { return state.q.toLowerCase().split(/\s+/).filter(Boolean); }

  function card(a, terms) {
    const b = el('button', 'card');
    b.type = 'button';
    b.setAttribute('aria-label', `${a.name}, ${catLabel[a.category]}`);
    const thumb = el('div', 'thumb' + (isFlat(a) ? ' flat' : ''));
    const img = el('img'); img.loading = 'lazy'; img.decoding = 'async'; img.alt = ''; img.src = heroOf(a);
    thumb.append(img);
    const body = el('div', 'card-body');
    body.append(el('p', 'card-cat', esc(catLabel[a.category])), el('h3', 'card-name', highlight(a.name, terms)));
    const facts = el('div', 'card-facts');
    if (a.dims) facts.append(el('span', 'fact' + (['size', 'height', 'footprint'].includes(state.sort) ? ' hl' : ''), esc(dimsLine(a.dims))));
    if (a.textureSize) facts.append(el('span', 'fact', esc(a.textureSize + ' px')));
    if (a.tris) facts.append(el('span', 'fact' + (state.sort === 'tris' ? ' hl' : ''), `${num(a.tris)} tris`));
    if (a.instances > 1) facts.append(el('span', 'fact' + (state.sort === 'instances' ? ' hl' : ''), `×${a.instances}`));
    body.append(facts);
    b.append(thumb, body);
    b.onclick = () => open(a.id);
    return b;
  }

  function renderGrid() {
    const grid = $('#grid'); grid.innerHTML = '';
    const terms = terms_();
    let list = data.assets.filter((a) => (state.cat === 'all' || a.categories.includes(state.cat)) && matches(a, terms));
    list = sortAssets(list);
    visible = list;
    const frag = document.createDocumentFragment();
    if (state.sort === 'category' || (state.sort === 'relevance' && !state.q)) {
      let current = null;
      for (const a of list) {
        if (a.category !== current) {
          current = a.category;
          const n = list.filter((x) => x.category === current).length;
          frag.append(el('h2', 'group-head', `${esc(catLabel[current])} <small>${n}</small>`));
        }
        frag.append(card(a, terms));
      }
    } else for (const a of list) frag.append(card(a, terms));
    grid.append(frag);
    $('#empty').hidden = list.length > 0;
    $('#count').textContent = `${list.length} of ${data.assets.length} assets${state.q ? ` matching “${state.q}”` : ''}`;
  }

  // ---------- detail ----------
  function section(title, content) { const s = el('section'); s.append(el('h3', '', esc(title))); s.append(typeof content === 'string' ? el('div', '', content) : content); return s; }
  function list_(items, cls = 'plain') { const u = el('ul', cls); for (const i of items) u.append(el('li', '', esc(i))); return u; }

  function renderDetail(a) {
    $('#d-cat').textContent = (a.categories || [a.category]).map((c) => catLabel[c]).join(' · ');
    $('#d-name').textContent = a.name;
    const stage = $('#d-stage');
    stage.classList.toggle('flat', isFlat(a));
    const img = $('#d-img'); const dl = $('#d-dl');
    const show = (v) => {
      img.src = v.file; img.alt = `${a.name}, ${v.label} view`;
      dl.href = v.file; dl.setAttribute('download', v.file.split('/').pop());
      for (const b of views.children) b.setAttribute('aria-pressed', String(b.dataset.view === v.view));
    };
    const views = $('#d-views'); views.innerHTML = '';
    for (const v of a.views) {
      const b = el('button', 'view-btn'); b.type = 'button'; b.dataset.view = v.view;
      b.innerHTML = `<img src="${esc(v.file)}" alt="" loading="lazy"><span>${esc(v.label)}</span>`;
      b.onclick = () => show(v);
      views.append(b);
    }
    views.hidden = a.views.length < 2;
    show(a.views.find((v) => v.view === 'hero') || a.views[0]);

    const info = $('#d-info'); info.innerHTML = '';
    info.append(el('p', 'lead', esc(a.description)));

    if (a.dims) {
      const d = el('div', 'dims');
      d.innerHTML = `<div class="dim"><b>${len(a.dims.w)}</b><span>Width (x)</span></div><div class="dim"><b>${len(a.dims.h)}</b><span>Height (y)</span></div><div class="dim"><b>${len(a.dims.d)}</b><span>Depth (z)</span></div>`;
      info.append(section('Size', d));
    }

    const kv = el('dl', 'kv');
    const row = (k, v) => { if (v == null || v === '') return; kv.append(el('dt', '', esc(k)), el('dd', '', esc(v))); };
    if (a.textureSize) row('Resolution', `${a.textureSize} px`);
    if (a.tris != null) row('Triangles', num(a.tris));
    if (a.verts != null) row('Vertices', num(a.verts));
    if (a.meshes != null) row('Meshes', num(a.meshes));
    if (a.instances) row('Copies in the bar', String(a.instances));
    if (a.pivot) row('Origin', a.pivot);
    if (a.scale) row('Character scale', `${a.scale}, ${a.bodyType}`);
    if (a.kind !== 'texture' && a.kind !== 'file') row('Facing', 'front faces +Z, Y up');
    row('Built in', a.source);
    if (kv.children.length) info.append(section('Details', kv));

    if (a.usedIn && a.usedIn.length) info.append(section('Where it appears', list_(a.usedIn)));
    if (a.notes && a.notes.length) info.append(section('Notes for the reskin', list_(a.notes, 'plain notes')));

    if (a.joints) {
      const t = el('table', 'joints');
      t.innerHTML = '<thead><tr><th>Joint</th><th>x</th><th>y</th><th>z</th></tr></thead>';
      const tb = el('tbody');
      for (const [name, p] of Object.entries(a.joints)) tb.append(el('tr', '', `<td>${esc(name)}</td>${p.map((v) => `<td>${v.toFixed(3)}</td>`).join('')}`));
      t.append(tb);
      const wrap = el('div'); wrap.append(t, el('p', '', '<small>Metres, in the neutral standing pose with the feet at the origin.</small>'));
      info.append(section('Rig: joint positions', wrap));
      if (a.rig) {
        info.append(section('Poses', el('div', 'chips', a.rig.poses.map((p) => `<span class="chip">${esc(p)}</span>`).join(''))));
        info.append(section('Animations', el('div', 'chips', a.rig.actions.map((p) => `<span class="chip">${esc(p)}</span>`).join(''))));
      }
    }

    if (a.materials && a.materials.length) {
      const m = el('div', 'mats');
      for (const mat of a.materials) {
        const sw = el('span', 'sw' + (mat.emissive ? ' glow' : ''));
        sw.style.background = mat.color || '#888';
        if (mat.emissive) sw.style.setProperty('--glow', mat.emissive);
        if (mat.opacity != null || mat.transmission) sw.style.opacity = '0.6';
        const bits = [mat.type];
        if (mat.roughness != null) bits.push(`roughness ${mat.roughness}`);
        if (mat.metalness) bits.push(`metal ${mat.metalness}`);
        if (mat.opacity != null) bits.push(`opacity ${mat.opacity}`);
        if (mat.transmission) bits.push(`transmission ${mat.transmission}`);
        if (mat.emissive) bits.push(`glows ${mat.emissive}`);
        if (mat.texture) bits.push(`texture: ${mat.texture}`);
        const row = el('div', 'mat'); const txt = el('span', '', `<code>${esc(mat.color || '—')}</code> · ${esc(bits.join(' · '))}`);
        row.append(sw, txt); m.append(row);
      }
      info.append(section(`Materials (${a.materials.length})`, m));
    }
    if (a.textures && a.textures.length) info.append(section('Textures', list_(a.textures.map((t) => `${t.name}: ${t.size} px${t.repeat ? `, repeated ${t.repeat}` : ''}`))));
    if (a.lights && a.lights.length) info.append(section('Lights it carries', list_(a.lights.map((l) => `${l.type} light ${l.color}, intensity ${l.intensity}${l.distance ? `, reach ${l.distance} m` : ''}`))));
    if (a.palette && a.palette.length > 1) {
      const p = el('div', 'palette');
      for (const c of a.palette) { const s = el('span', 'sw'); s.style.background = c; s.title = c; p.append(s); }
      info.append(section('Palette', p));
    }
    if (a.tags && a.tags.length) info.append(section('Tags', el('div', 'chips', a.tags.map((t) => `<span class="chip">${esc(t)}</span>`).join(''))));
    info.scrollTop = 0;
    $('.d-body').scrollTop = 0;
  }

  let lastFocus = null;
  function open(id) { state.asset = id; lastFocus = document.activeElement; update(); }
  function close() { state.asset = null; update(); if (lastFocus) lastFocus.focus(); }
  function step(d) {
    if (!state.asset || !visible.length) return;
    const i = visible.findIndex((a) => a.id === state.asset);
    const n = visible[(i + d + visible.length) % visible.length];
    state.asset = n.id; update();
  }

  // ---------- state <-> URL ----------
  function writeHash() {
    const p = new URLSearchParams();
    if (state.q) p.set('q', state.q);
    if (state.cat !== 'all') p.set('cat', state.cat);
    if (state.sort !== 'category') p.set('sort', state.sort);
    if (state.dir === -1) p.set('dir', 'desc');
    if (state.asset) p.set('asset', state.asset);
    const h = p.toString();
    if (('#' + h) !== location.hash && !(h === '' && location.hash === '')) history.replaceState(null, '', h ? '#' + h : location.pathname + location.search);
  }
  function readHash() {
    const p = new URLSearchParams(location.hash.slice(1));
    state.q = p.get('q') || '';
    state.cat = p.get('cat') || 'all';
    state.sort = key[p.get('sort')] ? p.get('sort') : 'category';
    state.dir = p.get('dir') === 'desc' ? -1 : 1;
    state.asset = p.get('asset');
  }

  function update() {
    $('#q').value !== state.q && ($('#q').value = state.q);
    $('#sort').value = state.sort;
    $('#dir').textContent = state.dir === 1 ? '↓' : '↑';
    $('#dir').title = state.dir === 1 ? 'Ascending (click to reverse)' : 'Descending (click to reverse)';
    renderCats();
    renderGrid();
    const a = state.asset && data.assets.find((x) => x.id === state.asset);
    $('#detail').hidden = !a;
    document.body.style.overflow = a ? 'hidden' : '';
    if (a) { renderDetail(a); setTimeout(() => $('#detail .d-nav [data-close]').focus(), 0); }
    writeHash();
  }

  // ---------- wiring ----------
  let qTimer;
  $('#q').addEventListener('input', (e) => {
    clearTimeout(qTimer);
    qTimer = setTimeout(() => {
      state.q = e.target.value.trim();
      // while searching, best matches first; back to the category view when the search is cleared
      if (state.q && state.sort === 'category') { state.sort = 'relevance'; state.dir = 1; }
      if (!state.q && state.sort === 'relevance') state.sort = 'category';
      update();
    }, 90);
  });
  $('#sort').addEventListener('change', (e) => {
    state.sort = e.target.value;
    // biggest / busiest first is the useful default for numeric sorts
    state.dir = ['size', 'height', 'footprint', 'tris', 'instances'].includes(state.sort) ? -1 : 1;
    update();
  });
  $('#dir').addEventListener('click', () => { state.dir = -state.dir; update(); });
  document.querySelectorAll('[data-close]').forEach((b) => b.addEventListener('click', close));
  $('#d-prev').addEventListener('click', () => step(-1));
  $('#d-next').addEventListener('click', () => step(1));
  document.addEventListener('keydown', (e) => {
    const typing = e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT';
    if (state.asset) {
      if (e.key === 'Escape') close();
      else if (e.key === 'ArrowRight') step(1);
      else if (e.key === 'ArrowLeft') step(-1);
      return;
    }
    if (e.key === '/' && !typing) { e.preventDefault(); $('#q').focus(); $('#q').select(); }
    else if (e.key === 'Escape' && e.target.id === 'q') { state.q = ''; if (state.sort === 'relevance') state.sort = 'category'; update(); }
  });
  addEventListener('hashchange', () => { readHash(); update(); });

  fetch('catalog.json').then((r) => r.json()).then((json) => {
    data = json;
    data.categories.forEach((c, i) => { catLabel[c.id] = c.label; catOrder[c.id] = i; });
    for (const a of data.assets) if (!a.categories || !a.categories.length) a.categories = [a.category];
    const c = data.conventions || {};
    $('#conventions').textContent = `Units: ${c.units || 'metres'} · Up: ${c.up || '+Y'} · Front: ${c.front || '+Z'}`;
    $('#generated').textContent = data.generated ? `Generated ${new Date(data.generated).toLocaleString()}.` : '';
    readHash();
    update();
  }).catch((e) => {
    $('#count').textContent = 'Could not load catalog.json: ' + e.message;
  });
})();
